using System;
using System.Collections.Generic;
using System.IO;
using System.Linq;
using Gearbound.Core;
using Gearbound.Workshop;
using NUnit.Framework;

namespace Gearbound.Tests
{
    /// <summary>
    /// Replays shared/test-fixtures/workshop_cases.json (generated by flutter/tool/workshop_cases.dart)
    /// through the C# WorkshopController and compares every step.
    /// </summary>
    public sealed class WorkshopFixtureTests
    {
        private static string root;

        private static string Shared(string rel)
        {
            if (root == null)
            {
                var dir = new DirectoryInfo(Directory.GetCurrentDirectory());
                while (dir != null && !Directory.Exists(Path.Combine(dir.FullName, "shared"))) dir = dir.Parent;
                Assert.IsNotNull(dir, "shared/ folder not found");
                root = dir.FullName;
            }
            return File.ReadAllText(Path.Combine(root, "shared", rel));
        }

        private static Dictionary<string, object> Fixture() =>
            SharedJson.Obj(SharedJson.Parse(Shared("test-fixtures/workshop_cases.json")), "workshop_cases");

        private static WorkshopController NewController(uint seed) => new WorkshopController(new GearBoard(),
            SharedDataLoader.LoadGears(Shared("gears/starter_gears.json")), SharedDataLoader.LoadShop(Shared("economy/shop.json")),
            WorkshopRules.Load(Shared("configs/gear_rules.json")), seed, () => new DateTime(2026, 1, 1, 0, 0, 0, DateTimeKind.Utc));

        private static string Camel(WorkshopAction a) { var s = a.ToString(); return char.ToLowerInvariant(s[0]) + s.Substring(1); }
        private static string Camel(NetworkState s) { var t = s.ToString(); return char.ToLowerInvariant(t[0]) + t.Substring(1); }

        private static (int X, int Y) Cell(object value)
        {
            var list = (List<object>)value;
            return (Convert.ToInt32(list[0]), Convert.ToInt32(list[1]));
        }

        private static string Snapshot(WorkshopController w, string result)
        {
            var board = w.Board.Nodes.OrderBy(n => n.Y).ThenBy(n => n.X)
                .Select(n => $"{n.Id}|{n.DefinitionId}|t{n.Tier}|{n.X},{n.Y}|lane{n.TargetLane}|{n.BaseIntervalTicks}");
            var sel = w.Selected.HasValue ? $"{w.Selected.Value.X},{w.Selected.Value.Y}" : "null";
            return $"result={result} scrap={w.BattleScrapBalance} offers=[{string.Join(",", w.Offers.Select(o => o ?? "null"))}] " +
                   $"hand={w.Hand?.Id ?? "null"} selected={sel} held=[{string.Join(",", w.Held.Select(h => h ? "true" : "false"))}] " +
                   $"rerolls={w.RerollsTaken} locked={w.Locked} board=[{string.Join(";", board)}]";
        }

        private static string Expected(Dictionary<string, object> s)
        {
            var offers = ((List<object>)s["offers"]).Select(o => (string)o ?? "null");
            var sel = s["selected"] is List<object> l ? $"{l[0]},{l[1]}" : "null";
            var board = ((List<object>)s["board"]).Cast<string>();
            return $"result={s["result"]} scrap={SharedJson.Int(s, "scrap")} offers=[{string.Join(",", offers)}] " +
                   $"hand={(string)s["hand"] ?? "null"} selected={sel} held=[{string.Join(",", ((List<object>)s["held"]).Select(h => (bool)h ? "true" : "false"))}] " +
                   $"rerolls={SharedJson.Int(s, "rerollsTaken")} " +
                   $"locked={((bool)s["locked"] ? "True" : "False")} board=[{string.Join(";", board)}]";
        }

        private static string Apply(WorkshopController w, Dictionary<string, object> op)
        {
            switch ((string)op["op"])
            {
                case "buy": return Camel(w.Buy(SharedJson.Int(op, "slot")));
                case "buyId": return Camel(w.Buy(Array.IndexOf(w.Offers, (string)op["id"])));
                case "tap": return Camel(w.TapCell(SharedJson.Int(op, "x"), SharedJson.Int(op, "y")));
                case "drop": return Camel(w.Drop(Cell(op["from"]), Cell(op["to"])));
                case "sell": return Camel(w.SellSelected());
                case "undo": return Camel(w.Undo());
                case "cancel": return Camel(w.CancelHand());
                case "reroll": return Camel(w.Reroll());
                case "hold": return Camel(w.ToggleHold(SharedJson.Int(op, "slot")));
                case "lock": w.Lock(); return "ok";
                case "intermission": return Camel(w.BeginIntermission(SharedJson.Int(op, "wave"), SharedJson.Int(op, "reward")));
                case "preview":
                    var p = w.PreviewAt(SharedJson.Int(op, "x"), SharedJson.Int(op, "y"),
                        op.TryGetValue("from", out var from) && from != null ? Cell(from) : default((int X, int Y)?));
                    return $"valid={(p.Valid ? "true" : "false")};state={(p.State.HasValue ? Camel(p.State.Value) : "null")};" +
                           $"interval={p.IntervalTicks};lane={(p.Lane.HasValue ? p.Lane.Value.ToString() : "null")}";
                default: throw new ArgumentException("unknown op " + op["op"]);
            }
        }

        [Test]
        public void MixSeed32MatchesSharedVectors()
        {
            foreach (var item in SharedJson.Arr(Fixture(), "mixSeed32"))
            {
                var v = SharedJson.Obj(item, "vector");
                Assert.AreEqual((uint)SharedJson.Long(v, "mixed"), SeededRandom.MixSeed32((uint)SharedJson.Long(v, "seed")), "seed " + v["seed"]);
            }
        }

        [Test]
        public void EveryCaseReplaysStepForStep()
        {
            var cases = SharedJson.Arr(Fixture(), "cases");
            Assert.GreaterOrEqual(cases.Count, 5);
            foreach (var item in cases)
            {
                var c = SharedJson.Obj(item, "case");
                var id = SharedJson.Str(c, "id");
                var w = NewController((uint)SharedJson.Long(c, "seed"));
                var ops = SharedJson.Arr(c, "ops");
                var steps = SharedJson.Arr(c, "steps");
                Assert.AreEqual(ops.Count + 1, steps.Count, id);
                Assert.AreEqual(Expected(SharedJson.Obj(steps[0], "step")), Snapshot(w, "start"), id + " start");
                for (var i = 0; i < ops.Count; i++)
                {
                    var result = Apply(w, SharedJson.Obj(ops[i], "op"));
                    Assert.AreEqual(Expected(SharedJson.Obj(steps[i + 1], "step")), Snapshot(w, result), $"{id} step {i + 1} ({ops[i]})");
                }
            }
        }

        [Test]
        public void SellingMergedGearRefundsEveryCopyAndUndoChargesItBack()
        {
            var w = NewController(1);
            Assert.AreEqual(WorkshopAction.Ok, w.Buy(Array.IndexOf(w.Offers, "unit.rivetguard")));
            Assert.AreEqual(WorkshopAction.Ok, w.TapCell(1, 3));
            w.TapCell(1, 2);
            Assert.AreEqual(WorkshopAction.Ok, w.TapCell(1, 3));
            Assert.AreEqual(2, w.Board.At(1, 2).Tier);
            Assert.AreEqual(63, w.Board.At(1, 2).BaseIntervalTicks); // 90 × 70% rounded up
            Assert.AreEqual(4, w.SelectedSellValue); // 2 copies × 50% of 5, rounded down per copy
            var before = w.BattleScrapBalance;
            Assert.AreEqual(WorkshopAction.Ok, w.SellSelected());
            Assert.AreEqual(before + 4, w.BattleScrapBalance);
            Assert.AreEqual(WorkshopAction.Ok, w.Undo());
            Assert.AreEqual(before, w.BattleScrapBalance);
            Assert.IsTrue(w.Wallet.Ledger.All(e => e.Asset == WorkshopController.BattleScrap));
        }

        [Test]
        public void CoreCannotBeSoldOrDroppedOnto()
        {
            var w = NewController(1);
            w.TapCell(0, 2);
            Assert.IsNull(w.Selected);
            Assert.AreEqual(WorkshopAction.Occupied, w.Drop((1, 2), (0, 2)));
            Assert.AreEqual(2, w.Board.Nodes.Count);
        }

        [Test]
        public void HeldOfferSurvivesRerollAndNextWaveUntilBought()
        {
            for (uint seed = 1; seed < 40; seed++)
            {
                var w = NewController(seed);
                var kept = w.Offers[1];
                Assert.AreEqual(WorkshopAction.Ok, w.ToggleHold(1));
                Assert.AreEqual(WorkshopAction.Ok, w.Reroll());
                Assert.AreEqual(kept, w.Offers[1], "seed " + seed);
                w.Lock();
                Assert.AreEqual(WorkshopAction.Locked, w.ToggleHold(0));
                w.BeginIntermission(1, 5);
                Assert.AreEqual(kept, w.Offers[1], "seed " + seed + " next wave");
                Assert.IsTrue(w.Held[1]);
                if (w.Buy(1) == WorkshopAction.Ok)
                {
                    Assert.IsFalse(w.Held[1]);
                    Assert.AreEqual(WorkshopAction.NoOffer, w.ToggleHold(1));
                }
            }
        }

        [Test]
        public void HoldingEveryOfferRefusesRerollWithoutCharging()
        {
            var w = NewController(7);
            for (var slot = 0; slot < 3; slot++) Assert.AreEqual(WorkshopAction.Ok, w.ToggleHold(slot));
            var scrap = w.BattleScrapBalance;
            Assert.AreEqual(WorkshopAction.AllHeld, w.Reroll());
            Assert.AreEqual(scrap, w.BattleScrapBalance);
            Assert.AreEqual(0, w.RerollsTaken);
        }

        [Test]
        public void WaveRewardIsPaidOncePerWave()
        {
            var w = NewController(3);
            w.Lock();
            w.BeginIntermission(1, 10);
            w.Lock();
            w.BeginIntermission(1, 10);
            Assert.AreEqual(22, w.BattleScrapBalance);
        }
    }
}
